// The social preview image for formweh.com, served at /og.png.
//
// Generated deterministically from assets/og-card.svg (a faithful SVG of
// assets/og-card.html). To regenerate after editing the card:
//   rsvg-convert -w 1200 -h 630 assets/og-card.svg -o assets/og.png
//   then base64 the PNG into OG_PNG_B64 below.
export const OG_PNG_B64 = ''

export function hasOgImage(): boolean {
  return OG_PNG_B64.length > 0
}
